/*
 * align.c -- prog-align lane against the real AGC code (yaAGC oracle).
 *
 * Inputs and expected words: tools/oracle/cases/align.spec / .txt
 * (Comanche055) and align_lm.spec / .txt (Luminary099), generated by
 * tools/oracle/cases/gen/gen_align.py.
 * Routines: SXTNB, SXTANG (incl. ZNB=S1 and the CULTFLAG trunnion alarm),
 * LOG (CSM_GEOMETRY); RRNB, RRANGLES (incl. mode 2 swap and the along-Y
 * exit) (LEM_GEOMETRY); SCALEVEC (R47, incl. the -0 rounding case);
 * the R05 S-band pitch/yaw computations of both vehicles.
 *
 * Tolerances are in LSB of the AGC word (0 = bit exact).  RRANGLES and
 * SXTANG convert the words ASIN/ACOS/ARCTRIG leave (word_forms.c), which
 * 12 random cases each confirm; KNOWN PA-W2: SXTNB (SIN's MPAC +2),
 * PA-W3: LM S-band pitch (ABVAL's MPAC +2 reaches ASIN).
 */
#include <stdio.h>

#include "agc/core/assert.h"
#include "agc/core/flags_common.h"
#include "agc/core/interp.h"
#include "agc/core/state.h"
#include "agc/programs/alignment.h"
#include "oracle_txt.h"

#define CULTFLAG_BIT 0100u /* CULTFLAG: FLAGWRD3 bit 7 */

bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

static agc_mat_t mat_in(const char *t, const char *name)
{
    agc_mat_t m;

    for (int r = 0; r < 3; r++)
    {
        m.row[r] = oracle_in_vec_at(t, name, r);
    }

    return (m);
}

/* CDU words compared modulo one revolution (2's complement, 15 bits). */
static void cmp_cdu(const char *t, const char *what, uint16_t got, const char *name, long tol)
{
    long d = ((long) got - (long) oracle_out_raw(t, name)) & 077777L;

    if (d >= 040000L)
    {
        d -= 0100000L;
    }

    (void) oracle_cmp(t, what, d, 0, tol);
}

static void rrnb(const char *t, long tol)
{
    agc_interp_t ip;
    agc_vec_t    los = agc_vec_zero();

    agc_interp_init(&ip);
    oracle_require_ok(t, "DSPLY81");
    (void) agc_lm_rrnb(&ip, oracle_in_raw(t, "TANGNB", 0), oracle_in_raw(t, "TANGNB", 1), &los);
    oracle_cmp_vec(t, "32D", los, oracle_out_vec(t, "VAC1+32"), tol);
}

static void rrangles(const char *t, bool along_y_expected, long tol)
{
    agc_interp_t ip;
    uint16_t     a[2]    = {0, 0};
    uint16_t     b[2]    = {0, 0};
    bool         along_y = false;
    agc_vec_t    los;

    agc_interp_init(&ip);
    oracle_require_ok(t, along_y_expected ? "LUNDESCH" : "POODOO");
    los.c[0] = oracle_in_dp(t, "MPAC", 0);
    los.c[1] = oracle_in_dp(t, "MPAC", 3);
    los.c[2] = oracle_in_dp(t, "MPAC", 5);
    (void) agc_lm_rrangles(&ip, los, oracle_in(t, "RADMODES", 0) != 0, a, b, &along_y);
    (void) oracle_cmp(t, "along_y", along_y ? 1 : 0, along_y_expected ? 1 : 0, 0);

    if (!along_y_expected)
    {
        cmp_cdu(t, "MODEA", a[0], "MODEA", tol);
        cmp_cdu(t, "MODEA+1", a[1], "MODEA+1", tol);
        cmp_cdu(t, "MODEB", b[0], "MODEB", tol);
        cmp_cdu(t, "MODEB+1", b[1], "MODEB+1", tol);
    }
}

static void scalevec(const char *t)
{
    static const char *const names[6] = {"MPAC", "MPAC+1", "MPAC+3", "MPAC+4", "MPAC+5", "MPAC+6"};
    agc_interp_t    ip;
    uint16_t        out[6]            = {0, 0, 0, 0, 0, 0};
    const agc_mat_t ref               = mat_in(t, "REFSMMAT");

    agc_interp_init(&ip);
    oracle_require_ok(t, "DSPLY81");
    (void) agc_ags_scalevec(&ip, oracle_in_vec(t, "VAC1+14"), oracle_in_vec(t, "VAC1+20"), &ref, out);

    for (int k = 0; k < 6; k++)
    {
        (void) oracle_cmp(t, names[k], (long) out[k], (long) oracle_out_raw(t, names[k]), 0);
    }
}

/* R05 (LM) angle part: UE = -UNIT(RATT), MXV identity VSL1, *SMNB* with
 * zero CDUs (exact), then the C angles routine.                        */
static void sband_lm(const char *t, long tol)
{
    agc_interp_t    ip;
    agc_dp_t        pitch = 0;
    agc_dp_t        yaw   = 0;
    const agc_mat_t ref   = mat_in(t, "REFSMMAT");

    agc_interp_init(&ip);
    oracle_require_ok(t, "42,3746");
    agc_vec_t ue = agc_vec_neg(agc_vec_unit(&ip, oracle_in_vec(t, "VAC1"), NULL, NULL));

    ue = agc_vec_shl(&ip, agc_mat_vec(&ip, &ref, ue), 1);
    (void) agc_sband_lm_angles(&ip, ue, &pitch, &yaw);

    /* ABVAL leaves MPAC +2 (e.g. 20000) and ASIN's SQRTSUB sees it; the
     * C ASIN takes a DP (review-prog-align.md W3): KNOWN at 0, hard at 1. */
    oracle_cmp_known(t, "PITCHANG", (long) pitch, (long) oracle_out_dp(t, "PITCHANG"), tol, "PA-W3");
    (void) oracle_cmp(t, "PITCHANG", (long) pitch, (long) oracle_out_dp(t, "PITCHANG"), tol + 1);
    (void) oracle_cmp(t, "YAWANG", (long) yaw, (long) oracle_out_dp(t, "YAWANG"), tol);
}

/* R05 (CSM) angle part from the AGC's own NB vector R (2D).            */
static void sband_cm(const char *t, long tol)
{
    agc_interp_t ip;
    agc_dp_t     pitch = 0;
    agc_dp_t     yaw   = 0;

    agc_interp_init(&ip);
    oracle_require_ok(t, "42,3751");
    (void) agc_sband_cm_angles(&ip, oracle_out_vec(t, "VAC1+2"), &pitch, &yaw);
    (void) oracle_cmp(t, "RHOSB", (long) pitch, (long) oracle_out_dp(t, "RHOSB"), tol);
    (void) oracle_cmp(t, "GAMMASB", (long) yaw, (long) oracle_out_dp(t, "GAMMASB"), tol);
}

static void sxtnb(const char *t, long tol)
{
    agc_interp_t ip;
    agc_vec_t    los = agc_vec_zero();

    agc_interp_init(&ip);
    oracle_require_ok(t, "POODOO");
    (void) agc_csm_sxtnb(&ip, oracle_in_raw(t, "VAC4+5", 0), oracle_in_raw(t, "VAC4+3", 0), &los);

    /* SXTNB's SIN SL1 shifts SIN's MPAC +2 into the result; agc_dp_sin
     * returns two words, so sin TA can be 1 LSB low and 32D 2 LSB off
     * (docs/modules/review-prog-align.md W2): KNOWN at 0, hard at 2.    */
    oracle_cmp_vec_known(t, "32D", los, oracle_out_vec(t, "VAC1+32"), tol, "PA-W2");
    oracle_cmp_vec(t, "32D", los, oracle_out_vec(t, "VAC1+32"), tol + 2);
}

static void sxtang(const char *t, long tol)
{
    agc_interp_t    ip;
    uint16_t        sac  = 0;
    uint16_t        pac  = 0;
    bool            cult = false;
    const agc_mat_t nb   = mat_in(t, "XNB");

    agc_interp_init(&ip);
    oracle_require_ok(t, "POODOO");
    (void) agc_csm_sxtang(&ip, oracle_in_vec(t, "STAR"), &nb, &sac, &pac, &cult);
    cmp_cdu(t, "SAC", sac, "SAC", tol);
    const bool agc_cult = (oracle_out_raw(t, "FLAGWRD3") & CULTFLAG_BIT) != 0;

    (void) oracle_cmp(t, "CULTFLAG", cult ? 1 : 0, agc_cult ? 1 : 0, 0);

    if (!agc_cult)
    {
        cmp_cdu(t, "PAC", pac, "PAC", tol);
    }
}

static void log_case(const char *t, long tol)
{
    agc_interp_t ip;
    agc_dp_t     l = 0;

    agc_interp_init(&ip);
    oracle_require_ok(t, "POODOO");
    (void) agc_csm_log(&ip, oracle_in_dp(t, "MPAC", 0), &l);
    (void) oracle_cmp(t, "MPAC", (long) l, (long) oracle_out_dp(t, "MPAC"), tol);
}

int main(void)
{
    if (!oracle_load("align_lm"))
    {
        (void) printf("oracle_align: SKIP (case files not found)\n");

        return (0);
    }

    agc_state_init(AGC_VEHICLE_LM);
    rrnb("rrnb_a", 0);
    rrnb("rrnb_b", 0);
    rrnb("rrnb_c", 0);
    rrangles("rrangles_a", false, 0);
    rrangles("rrangles_b", false, 0);
    rrangles("rrangles_mode2", false, 0);
    rrangles("rrangles_alongy", true, 0);
    rrangles("rrangles_y0", false, 0);
    rrangles("rrangles_x0", false, 0);

    for (int k = 0; k < 12; k++)
    {
        char tag[32];

        (void) snprintf(tag, sizeof tag, "rrangles_r%d", k);
        rrangles(tag, false, 0);
    }

    scalevec("scalevec_a");
    scalevec("scalevec_small");
    scalevec("scalevec_b");
    sband_lm("sband_lm_a", 0);
    sband_lm("sband_lm_b", 0);
    sband_lm("sband_lm_c", 0);
    sband_lm("sband_lm_d", 0);

    if (!oracle_load("align"))
    {
        (void) printf("oracle_align: SKIP (case files not found)\n");

        return (0);
    }

    agc_state_init(AGC_VEHICLE_CSM);
    sxtnb("sxtnb_a", 0);
    sxtnb("sxtnb_b", 0);
    sxtnb("sxtnb_c", 0);
    sxtang("sxtang_a", 0);
    sxtang("sxtang_b", 0);
    sxtang("sxtang_wide", 0);
    sxtang("sxtang_behind", 0);
    sxtang("sxtang_axis", 0);

    for (int k = 0; k < 12; k++)
    {
        char tag[32];

        (void) snprintf(tag, sizeof tag, "sxtang_r%d", k);
        sxtang(tag, 0);
    }

    log_case("log_half", 0);
    log_case("log_03", 0);
    log_case("log_small", 0);
    log_case("log_near1", 0);
    sband_cm("sband_cm_a", 0);
    sband_cm("sband_cm_b", 0);
    sband_cm("sband_cm_c", 0);
    sband_cm("sband_cm_d", 0);

    return (oracle_finish("oracle_align"));
}
